#!/bin/env python

# -> may need rerun by Edan to compute the bands distance for the chessboard graph
# note: the unit of the distance is in meV

# this script depend on "pseudo-to-bands-uuid-mapping.json", generated by the #002 script.

# The 1st result of running this script is to get a curated json group by elements.
# The 2nd result of running this script is to produce a json file "bands-distance.json" store the bands
# distances for each pair of pseudos of one element.
# The data format is:
# {
#     "Si": {
#         "pseudos":  {
#             "Si.us.pbe.z_4.ld1.psl.v1.0.0-low.upf": 0,
#             "Si.us.pbe.z_4.ld1.psl.v0.1.upf": 1,
#             "Si.paw.pbe.z_4.ld1.psl.v0.1.upf": 2,
#         },
#         "v-distance": {
#             "0-1": {
#                 "eta_c": eta_c, 
#                 "max_diff_c": max_diff_c, 
#                 "shift_c": shift_c
#             },
#             "0-2": ..,
#         },
#         "v10-distance": {
#             "0-1": {
#                 "eta_c": eta_c, 
#                 "max_diff_c": max_diff_c, 
#                 "shift_c": shift_c
#             },
#             "0-2": ..,
#         },
#     }
#     "Ag": ...
# }
# Every elements has key pseudos contains mapping from a label to an index.
# The "v-distance" ("v10" is for distance computed from include +10 eV above fermi level bands)
# key can retrieve the distance for each pair.
# depents on the requirements, may also need to dump the optimal offset for each pair.

import json
import copy
from typing import Any
import itertools

import aiida
from aiida import orm
from aiida_sssp_workflow.calculations.calculate_bands_distance import get_bands_distance

aiida.load_profile("full-24-07")

with open("pseudo-to-bands-uuid-mapping.json", mode="r") as fh:
    mapping = json.load(fh)

# curated by elements
curated = {}

for k, v in mapping.items():
    element = k.split(".")[0]
    curated.setdefault(element, {}).update({k: v})

with open("banddata_curated_by_element.json", mode="w") as fh:
    json.dump(curated, fh, indent=4)


# call as compute_chessboard("Si", curated)
def compute_chessboard(
    element: str,
    mapping: dict,
) -> dict[str, Any]:
    res = {}
    data = mapping[element]

    res_pseudos = {}
    for idx, (k, _) in enumerate(data.items()):
        res_pseudos.update({k: idx})

    # v-distance and v10 distance
    v_dist = {}
    v10_dist = {}
    for (p1, p2) in itertools.combinations(res_pseudos.keys(), 2):
        print(f"on {p1} - {p2}")

        vp1 = data[p1]
        vp2 = data[p2]

        idxp1 = res_pseudos[p1]
        idxp2 = res_pseudos[p2]
        
        band_structure_r: orm.BandsData = orm.load_node(vp1["banddata-node"])
        band_parameters_r: orm.Dict = orm.load_node(vp1["bandpara-node"])

        bandsdata_r = {
            "number_of_electrons": band_parameters_r["number_of_electrons"],
            "number_of_bands": band_parameters_r["number_of_bands"],
            "fermi_level": band_parameters_r["fermi_energy"],
            "bands": band_structure_r.get_bands(),
            "kpoints": band_structure_r.get_kpoints(),
            "weights": band_structure_r.get_array("weights"),
        }

        # smearing width is from degauss
        smearing = orm.load_node(vp1["workchain-node"]).inputs.bands.pw.parameters.get_dict()["SYSTEM"]["degauss"]

        # always do smearing on high bands and not include the spin since we didn't turn on the spin for all
        # convergence test, but this may change in the future.
        # The `get_bands_distance` function can deal with mag bands with spin_up and spin_down
        spin = False
        do_smearing = True

        xs = []
        ys_eta_c = []
        ys_max_diff_c = []

        band_structure_p: orm.BandsData = orm.load_node(vp2["banddata-node"])
        band_parameters_p: orm.Dict = orm.load_node(vp2["bandpara-node"])

        # The raw implementation of `get_bands_distance` is in `aiida_sssp_workflow/calculations/bands_distance.py`
        bandsdata_p = {
            "number_of_electrons": band_parameters_p["number_of_electrons"],
            "number_of_bands": band_parameters_p["number_of_bands"],
            "fermi_level": band_parameters_p["fermi_energy"],
            "bands": band_structure_p.get_bands(),
            "kpoints": band_structure_p.get_kpoints(),
            "weights": band_structure_p.get_array("weights"),
        }

        # v + 10 eV
        res = get_bands_distance(
            copy.deepcopy(bandsdata_r),
            copy.deepcopy(bandsdata_p),
            smearing=smearing,
            fermi_shift=10.0,
            do_smearing=do_smearing,
            spin=spin,
        )
        eta_c = res.get("eta_c", None)
        shift_c = res.get("shift_c", None)
        max_diff_c = res.get("max_diff_c", None)
        # unit = res.get("unit", None)

        v10_dist[f"{idxp1}-{idxp2}"] = {
            "eta_c": eta_c, 
            "max_diff_c": max_diff_c, 
            "shift_c": shift_c
        }

        # v + 0 eV
        res = get_bands_distance(
            copy.deepcopy(bandsdata_r),
            copy.deepcopy(bandsdata_p),
            smearing=smearing,
            fermi_shift=0.0,
            do_smearing=do_smearing,
            spin=spin,
        )
        eta_c = res.get("eta_c", None)
        shift_c = res.get("shift_c", None)
        max_diff_c = res.get("max_diff_c", None)
        # unit = res.get("unit", None)

        v_dist[f"{idxp1}-{idxp2}"] = {
            "eta_c": eta_c, 
            "max_diff_c": max_diff_c, 
            "shift_c": shift_c
        }



    res = {
        "pseudos": res_pseudos,
        "v-distance": v_dist,
        "v10-distance": v10_dist,
    }

    return res

final_curated = {}
for k, _ in curated.items():
    v = compute_chessboard(k, curated)
    final_curated[k] = v

with open("bands_distance.json", mode="w") as fh:
    json.dump(final_curated, fh, indent=4)

